function topologyAddressEntries(id,stage){
 const entries=[],consoleAddress=state.settings.topologyAddresses?.[id];
 if(consoleAddress)entries.push({label:'Management console',value:consoleAddress});
 if(id==='plc'){
  if(state.settings.topologyAddresses?.plcConfigured)entries.push({label:'Configured PLC address',value:state.settings.topologyAddresses.plcConfigured});
  if(stage>=8&&state.revealedTopologyAddresses.plcChanged)entries.push({label:'Observed changed address',value:state.revealedTopologyAddresses.plcChanged});
 }
 if(id==='win7'&&state.revealedTopologyAddresses.engineering)entries.push({label:'Verified Engineering Station',value:state.revealedTopologyAddresses.engineering});
 return entries;
}
function topologyDeviceDetailsMarkup(stage){
 const node=topologyGraphNodes.find(n=>n.id===state.topologySelectedNode&&stage>=n.stage);
 if(!node)return'<section class="topology-device-details" id="topology-device-details" aria-live="polite"><h3>Device details</h3><p>Select a system in the diagram or list to see its address and role.</p></section>';
 const entries=topologyAddressEntries(node.id,stage),plcHidden=node.id==='plc'&&stage>=8&&!state.revealedTopologyAddresses.plcChanged,engineeringHidden=node.id==='win7'&&stage>=16&&!state.revealedTopologyAddresses.engineering;
 return'<section class="topology-device-details" id="topology-device-details" aria-live="polite"><p class="eyebrow">Selected system</p><h3>'+esc(node.name)+'</h3><p>'+esc(node.sub)+'</p>'+(entries.length?'<dl>'+entries.map(item=>'<div><dt>'+esc(item.label)+'</dt><dd><code>'+esc(item.value)+'</code></dd></div>').join('')+'</dl>':'<p class="small-muted">No fixed address is listed for this system yet.</p>')+(plcHidden?'<p class="address-locked">The changed PLC address appears after you solve the PLC challenge.</p>':'')+(engineeringHidden?'<p class="address-locked">The Engineering Station address appears after its verification challenge.</p>':'')+'</section>';
}
function challengeAddressMarkup(c,plan){
 const entries=plan.nodes.flatMap(id=>topologyAddressEntries(id,topologyStageForChallenge(c)).map(item=>({name:topologyGraphNodes.find(n=>n.id===id)?.name||id,...item})));
 if(!entries.length)return'';
 return'<div class="challenge-addresses" aria-label="Known addresses for this challenge"><strong>Known addresses</strong>'+entries.map(item=>'<span><b>'+esc(item.name)+'</b> · '+esc(item.label)+': <code>'+esc(item.value)+'</code></span>').join('')+'</div>';
}
