function safeHtml(source){
 const doc=new DOMParser().parseFromString("<body>"+source+"</body>","text/html");
 const allowed=new Set(["A","P","BR","HR","H1","H2","H3","H4","H5","H6","STRONG","B","EM","I","U","CODE","PRE","BLOCKQUOTE","UL","OL","LI","DIV","SPAN","SECTION","ARTICLE","HEADER","FOOTER","FIGURE","FIGCAPTION","DETAILS","SUMMARY","TABLE","THEAD","TBODY","TR","TH","TD","IMG"]),attrs=new Set(["href","src","alt","title","target","rel","colspan","rowspan","width","height"]);
 function walk(n){for(const el of [...n.childNodes]){if(el.nodeType===8){el.remove();continue}if(el.nodeType!==1)continue;if(["SCRIPT","STYLE","IFRAME","OBJECT","EMBED","FORM","INPUT","BUTTON"].includes(el.tagName)){el.remove();continue}if(!allowed.has(el.tagName)){walk(el);el.replaceWith(...el.childNodes);continue}for(const a of [...el.attributes]){if(!attrs.has(a.name.toLowerCase()))el.removeAttribute(a.name);else if((a.name==="href"||a.name==="src")&&!/^(https?:|mailto:|\/|#)/i.test(a.value))el.removeAttribute(a.name)}if(el.tagName==="A"&&el.getAttribute("target")==="_blank")el.setAttribute("rel","noopener noreferrer");if(el.tagName==="IMG"){el.tabIndex=0;el.setAttribute("role","button");el.setAttribute("aria-haspopup","dialog");el.setAttribute("aria-label","Open image: "+(el.getAttribute("alt")||"challenge image"))}walk(el)}}
 walk(doc.body);return doc.body.innerHTML;
}
function markdown(source){
 let s=String(source||""),tick=String.fromCharCode(96);
 s=s.replace(new RegExp(tick+tick+tick+"([\\s\\S]*?)"+tick+tick+tick,"g"),(_,x)=>"<pre><code>"+esc(x.trim())+"</code></pre>");
 s=s.replace(new RegExp(tick+"([^"+tick+"]+)"+tick,"g"),"<code>$1</code>");
 s=s.replace(/!\[([^\]]*)\]\(([^)]+)\)/g,(_,alt,src)=>"<img src=\""+esc(src)+"\" alt=\""+esc(alt)+"\">");
 s=s.replace(/^######\s+(.+)$/gm,"<h6>$1</h6>").replace(/^#####\s+(.+)$/gm,"<h5>$1</h5>").replace(/^####\s+(.+)$/gm,"<h4>$1</h4>").replace(/^###\s+(.+)$/gm,"<h3>$1</h3>").replace(/^##\s+(.+)$/gm,"<h2>$1</h2>").replace(/^#\s+(.+)$/gm,"<h1>$1</h1>");
 s=s.replace(/\[([^\]]+)\]\(([^)]+)\)/g,'<a href="$2">$1</a>').replace(/\*\*([^*]+)\*\*/g,"<strong>$1</strong>").replace(/\*([^*]+)\*/g,"<em>$1</em>").replace(/^>\s?(.*)$/gm,"<blockquote>$1</blockquote>").replace(/^\s*[-*]\s+(.+)$/gm,"<li>$1</li>");
 s=s.replace(/(?:<li>.*<\/li>\n?)+/g,m=>"<ul>"+m+"</ul>");
 s=s.split(/\n{2,}/).map(b=>/^\s*<(h\d|ul|ol|pre|blockquote|div|section|table|hr|img|article|footer)/i.test(b.trim())?b:"<p>"+b.replace(/\n/g,"<br>")+"</p>").join("\n");
 return safeHtml(s);
}
const date=v=>{try{return v?new Date(v).toLocaleString():"—"}catch{return v||"—"}},nameOf=u=>u?.displayName||u?.username||"Participant",glyph={home:"⌂",challenges:"◈",scoreboard:"▤",vendors:"◇",topology:"⌘",admin:"⚙",menu:"☰"};
function navLink(label,view,key,active){const notice=key==="topology"&&state.topologyNotice?'<span class="nav-update-pill" aria-label="Topology updated">Updated</span>':key==="challenges"&&state.challengeNotice?'<span class="nav-update-pill challenge-notice" aria-label="New challenge available">New</span>':'';return'<a href="#" class="nav-link '+(active?"active":"")+'" data-view="'+view+'"><span class="nav-icon">'+glyph[key]+'</span>'+esc(label)+notice+"</a>"}
function shell(content,title){
 document.documentElement.style.setProperty("--accent",/^#[0-9a-f]{6}$/i.test(state.settings.accent)?state.settings.accent:"#c02678");
 const v=state.view;
 app.innerHTML='<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><span class="brand-mark">HB</span><div class="brand-copy"><strong>'+esc(state.settings.title)+'</strong><span>OT / IT workshop</span></div></div><nav class="nav-group"><p class="nav-label">Workshop</p>'+navLink("Overview","home","home",v==="home")+navLink("Challenges","challenges","challenges",v==="challenges")+navLink("Network topology","topology","topology",v==="topology")+(state.user?navLink("Check my lab","lab","topology",v==="lab"):"")+(state.settings.showScoreboard?navLink("Scoreboard","scoreboard","scoreboard",v==="scoreboard"):"")+'</nav><nav class="nav-group"><p class="nav-label">Explore</p>'+navLink("Products & vendors","vendors","vendors",v==="vendors")+(state.pages.some(p=>p.slug==="credentials")?navLink("Credentials","page:credentials","vendors",v==="page:credentials"):"")+(v.startsWith("page:")&&v!=='page:credentials'?navLink(title,v,"vendors",true):"")+'</nav>'+(state.user?.role==="admin"?'<nav class="nav-group"><p class="nav-label">Manage</p>'+navLink("Admin studio","admin","admin",v==="admin")+"</nav>":"")+'<div class="nav-spacer"></div><div class="sidebar-foot">'+esc(state.settings.footer||"Local workshop")+'</div></aside><main class="main"><header class="topbar"><div class="top-actions"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open menu">'+glyph.menu+'</button><span class="crumb">'+esc(title)+'</span></div><div class="top-actions">'+(state.user?'<span class="user-pill">'+esc(nameOf(state.user))+(state.user.role==="admin"?" · Admin":"")+'</span><button class="button ghost small" data-action="logout">Sign out</button>':'<button class="button ghost small" data-action="auth" data-mode="login">Sign in</button>'+(state.settings.registrationOpen?'<button class="button primary small" data-action="auth" data-mode="register">Join</button>':""))+'</div></header><div class="page-wrap">'+content+'</div></main></div>';
}
function groups(list){
 if(!list.length)return'<div class="empty">No challenges have been published yet.</div>';
 const map=new Map();for(const c of list){if(!map.has(c.category))map.set(c.category,[]);map.get(c.category).push(c)}
 return'<div class="challenge-groups">'+[...map].map(([cat,items])=>'<section><h3 class="category-title">'+esc(cat)+'</h3><div class="challenge-grid">'+items.map(c=>{const role=roleForText(c.title+" "+c.category);return'<button class="challenge-card '+(c.locked?"locked":"")+'"'+(role?' data-role="'+role+'"':'')+' data-challenge="'+esc(c.id)+'"><div class="card-top"><span class="badge '+(c.solved?"solved":c.skipped?"skipped":c.locked?"locked":"")+'">'+(c.solved?"✓ Complete":c.skipped?"↷ Skipped":c.locked?"⌑ Locked":"Open")+'</span><span class="small-muted">'+Number(c.points||0)+' pts</span></div>'+roleChip(role)+'<h3>'+esc(c.title)+'</h3><div class="card-bottom"><span>'+(c.requiresApproval?"Instructor review":(c.hints||[]).length+" hints")+'</span><span>'+(c.solved?"Solved →":c.skipped?"Skipped →":"Open →")+'</span></div></button>'}).join("")+'</div></section>').join("")+'</div>';
}
function overviewRoadmapMarkup(source){
 const raw=String(source||"").trim(),heading=/^###\s+(.+?)\s*$/gm,matches=[...raw.matchAll(heading)];
 if(!matches.length)return '<article class="surface markdown overview-intro">'+markdown(raw)+'</article>';
 const intro=raw.slice(0,matches[0].index).trim();
 const cards=matches.map((m,i)=>{const end=matches[i+1]?.index??raw.length,body=raw.slice(m.index+m[0].length,end).trim(),rawTitle=m[1].trim(),role=roleForPhase(rawTitle),title=rawTitle.replace(/^\[(?:Attacker|Defender|Both)\]\s*/i,"");return '<article class="overview-phase"'+(role?' data-role="'+role+'"':'')+'><span class="overview-phase-index">'+String(i+1).padStart(2,"0")+'</span><div class="overview-phase-copy"><div class="phase-heading">'+roleChip(role)+'<h3>'+esc(title)+'</h3></div><div class="markdown">'+markdown(body)+'</div></div></article>'}).join("");
 return '<div class="overview-roadmap">'+(intro?'<article class="surface markdown overview-intro">'+markdown(intro)+'</article>':"")+'<div class="role-legend"><span class="role-chip role-chip-attacker">Attacker</span><span class="role-chip role-chip-defender">Defender</span><span class="role-chip role-chip-both">Shared activity</span></div><div class="overview-phase-grid">'+cards+'</div></div>';
}
const incidentMilestones=[
  {min:0,title:'Production is running',body:'Build the PLC and establish a baseline before the attacker gains access.',tone:'calm'},
  {min:1,title:'Intrusion detected in OT',body:'An attacker foothold is active on the engineering station. Follow the route before it reaches the controller.',tone:'danger'},
  {min:8,title:'The PLC is disrupted',body:'The controller address has changed. The brewery process is at risk; investigate the OT event.',tone:'danger'},
  {min:14,title:'Ransomware is spreading',body:'Windows systems in OT and IT are affected. Production and recovery depend on a rapid defender response.',tone:'critical'},
  {min:15,title:'Recovery is underway',body:'SentinelOne has rolled back the affected Windows systems. The PLC still needs attention.',tone:'recovery'},
  {min:19,title:'The workshop response is complete',body:'IT and OT Windows systems are protected. Review the remaining PLC condition and your final network map.',tone:'recovery'}
];
function incidentMarkup(){const stage=Math.max(0,...state.challenges.filter(c=>c.solved).map(topologyStageForChallenge)),m=[...incidentMilestones].reverse().find(x=>stage>=x.min);return'<section class="incident-status '+m.tone+'" role="status"><span class="incident-signal" aria-hidden="true">'+(m.tone==='critical'?'!':m.tone==='recovery'?'✓':'●')+'</span><div><p class="eyebrow">BREWERY STATUS · PHASE '+String(stage).padStart(2,'0')+'</p><h2>'+m.title+'</h2><p>'+m.body+'</p></div><button class="button secondary small" data-view="topology">See the incident map →</button></section>'}
function home(){
 const visible=state.challenges.filter(c=>c.visible).sort((a,b)=>a.order-b.order||a.title.localeCompare(b.title));
 const solved=visible.filter(c=>c.solved||c.skipped).length,total=visible.length,score=Number(state.progress?.score)||0,current=currentWorkshopChallenge(),position=current?visible.findIndex(c=>c.id===current.id):-1;
 const artwork=String(state.settings.overviewArtwork||"").trim();
 const artworkMarkup=artwork?'<div class="home-artwork"><img src="'+esc(artwork)+'" alt="'+esc(state.settings.title)+' — hands-on OT cybersecurity workshop"></div>':'';
 const hero='<section class="home-hero">'+artworkMarkup+'<div class="home-hero-intro"><div><p class="eyebrow">YOUR WORKSHOP</p><h1>'+esc(state.settings.title)+'</h1><p>'+esc(state.settings.description||state.settings.tagline)+'</p></div><span class="home-hero-mode">OT <span>×</span> IT</span></div></section>';
 const currentButton=current?(state.user?'<button class="button primary" data-action="home-current-challenge" data-id="'+esc(current.id)+'">'+(solved?'Continue challenge':'Start workshop')+' <span aria-hidden="true">→</span></button>':'<button class="button primary" data-action="auth" data-mode="login">Sign in to begin <span aria-hidden="true">→</span></button>'):'<button class="button primary" data-view="topology">View your completed map <span aria-hidden="true">→</span></button>';
 const currentMarkup='<section class="home-current surface"><div class="home-current-main"><p class="eyebrow">'+(current?'YOUR NEXT CHALLENGE':'WORKSHOP COMPLETE')+'</p><h2>'+esc(current?.title||'You completed every activity')+'</h2><p>'+(current?'Complete the objective to unlock the next challenge. Flags also update your network map.':'Review the full network story and your finished challenges.')+'</p><div class="home-current-actions">'+currentButton+'<button class="button secondary" data-view="topology">Explore network topology</button></div></div><div class="home-current-progress"><div class="home-progress-head"><strong>'+solved+' of '+total+'</strong><span>activities complete</span></div><div class="home-progress-track" role="progressbar" aria-label="Workshop progress" aria-valuemin="0" aria-valuemax="'+total+'" aria-valuenow="'+solved+'"><span style="width:'+Math.round(total?solved/total*100:0)+'%"></span></div><div class="home-progress-foot"><span>'+Math.round(total?solved/total*100:0)+'% complete</span><span>'+score+' points earned</span></div></div></section>';
 const introduction=visible.filter(c=>/^0\.?\s*introduction\b/i.test(c.category)).slice(0,3);
 const setup=introduction.length?'<section class="home-section"><div class="home-section-head"><div><p class="eyebrow">BEFORE THE INCIDENT</p><h2>Get the lab ready</h2><p>These short activities introduce the rules, the interface, and the virtual PLC before initial access.</p></div></div><div class="home-setup-grid">'+introduction.map((c,i)=>'<button class="home-setup-step '+(c.solved||c.skipped?'is-done':c.locked?'is-locked':'is-current')+'" data-challenge="'+esc(c.id)+'" '+(c.locked?'disabled':'')+'><span class="home-setup-number">'+String(i+1).padStart(2,'0')+'</span><span class="home-setup-copy"><strong>'+esc(c.title)+'</strong><small>'+(c.solved?'Completed':c.skipped?'Skipped by facilitator':c.locked?'Unlocks after the previous step':'Ready to open')+'</small></span><span class="home-setup-status" aria-hidden="true">'+(c.solved?'✓':c.skipped?'↷':c.locked?'·':'→')+'</span></button>').join('')+'</div></section>':'';
 const roadmap='<section class="home-section"><div class="home-section-head"><div><p class="eyebrow">THE STORY</p><h2>What you will do</h2><p>'+esc(state.settings.welcome||'Follow the incident and the response, one unlocked challenge at a time.')+'</p></div><button class="button ghost small" data-view="challenges">All challenges →</button></div>'+overviewRoadmapMarkup(state.settings.overview)+'</section>';
 const resources='<section class="home-section home-resources"><div class="home-section-head"><div><p class="eyebrow">WORKSHOP TOOLS</p><h2>Find your way around</h2></div></div><div class="home-resource-grid"><button class="home-resource" data-view="topology"><span class="home-resource-icon">⌘</span><span><strong>Network topology</strong><small>See systems and connections as your flags unlock them.</small></span><b aria-hidden="true">→</b></button><button class="home-resource" data-view="vendors"><span class="home-resource-icon">◇</span><span><strong>Products & vendors</strong><small>Meet the tools you will use in the lab.</small></span><b aria-hidden="true">→</b></button>'+(state.pages.some(p=>p.slug==='credentials')?'<button class="home-resource" data-view="page:credentials"><span class="home-resource-icon">⌑</span><span><strong>Credentials</strong><small>Find the workshop sign-in details when you need them.</small></span><b aria-hidden="true">→</b></button>':'')+'</div></section>';
 shell('<div class="home-page">'+hero+incidentMarkup()+currentMarkup+setup+roadmap+resources+'<div class="footer">'+esc(state.settings.footer||'')+'</div></div>',"Overview");
}
