function pageIntro(body){return String(body||'').replace(/^#\s+[^\n]+\n?/,'').trim()}
function productGuide(body){
 const source=String(body||'').trim(),sections=[...source.matchAll(/^###\s+(.+)$/gm)];
 if(!sections.length)return'<article class="surface markdown vendor-intro">'+markdown(source)+'</article>';
 const intro=source.slice(0,sections[0].index).replace(/^##\s+Products.*$/gmi,'').trim();
 const cards=sections.map((match,i)=>{const end=sections[i+1]?.index??source.length,raw=source.slice(match.index+match[0].length,end).trim(),photo=raw.match(/!\[([^\]]*)\]\((\/images\/[^)]+|\/logos\/[^)]+)\)/),copy=photo?raw.replace(photo[0],'').trim():raw;return'<article class="product-feature">'+(photo?'<figure class="product-photo"><img src="'+esc(photo[2])+'" alt="'+esc(photo[1])+'" loading="lazy" tabindex="0" role="button" aria-haspopup="dialog"><figcaption>'+esc(photo[1])+'</figcaption></figure>':'')+'<div class="product-feature-copy"><span class="vendor-kicker">PRODUCT '+String(i+1).padStart(2,'0')+'</span><h2>'+esc(match[1])+'</h2><div class="markdown">'+markdown(copy)+'</div></div></article>'}).join('');
 return'<article class="surface markdown vendor-intro">'+markdown(intro)+'</article><div class="product-feature-list">'+cards+'</div>';
}
async function productCatalog(body){
 const items=state.pages.filter(x=>x.kind==='vendor');
 const loaded=await Promise.all(items.map(async x=>{try{return{...x,body:(await api('/api/pages/'+encodeURIComponent(x.slug))).body}}catch{return{...x,body:''}}}));
 const groups=[['Attacker tools and lab systems',loaded.filter(x=>['adaptix-c2','siemens'].includes(x.slug))],['Defender products',loaded.filter(x=>!['adaptix-c2','siemens'].includes(x.slug))]];
 const cards=group=>group.map(x=>{const text=pageIntro(x.body,x.title).split(/^###\s+/m)[0].replace(/^##.*$/gm,'').trim().split(/\n\s*\n/)[0];return'<button class="catalog-product-card" data-page="'+esc(x.slug)+'"><span class="catalog-product-logo">'+(x.logo?'<img src="'+esc(x.logo)+'" alt="'+esc(x.title)+' logo" loading="lazy">':esc(x.title.slice(0,2)))+'</span><span class="catalog-product-copy"><strong>'+esc(x.title)+'</strong><span>'+esc(text)+'</span><b>Explore products →</b></span></button>'}).join('');
 return'<div class="product-catalog"><div class="surface markdown catalog-intro">'+markdown(body)+'</div>'+groups.filter(([,items])=>items.length).map(([heading,items])=>'<section><h2>'+esc(heading)+'</h2><div class="catalog-product-grid">'+cards(items)+'</div></section>').join('')+'</div>';
}
async function openPage(slug){const meta=state.pages.find(x=>x.slug===slug);if(meta?.authRequired&&!state.user){shell('<p class="eyebrow">Lab reference</p><h1 class="page-title">'+esc(meta.title)+'</h1><div class="surface"><p>Sign in to view the workshop credentials assigned to participants.</p><button class="button primary" data-action="auth" data-mode="login">Sign in to continue</button></div>',meta.title);return}const d=await api("/api/pages/"+encodeURIComponent(slug));state.pageSlug=slug;const lines=String(d.body||'').split(/\r?\n/);if(lines[0]?.replace(/^#\s*/,"").trim().toLowerCase()===d.title.toLowerCase())lines.shift();const content=lines.join("\n").trim();const back=state.challengeReturnContext?'<div class="reference-return"><button class="button secondary small" data-action="return-challenge">← Back to '+esc(state.challengeReturnContext.title||'challenge')+'</button><p class="small-muted">Your flag draft and open hints are kept while you read this reference.</p></div>':'';const body=d.kind==='catalog'?await productCatalog(content):d.kind==='vendor'?productGuide(content):'<article class="surface markdown">'+markdown(content)+'</article>';shell(back+'<p class="eyebrow">'+(d.kind==='vendor'?'Vendor reference':d.kind==='catalog'?'Workshop reference':'Workshop page')+'</p><h1 class="page-title">'+esc(d.title)+'</h1>'+body,d.title)}
