function routeView(){if(state.view==="lab")labCheck();else if(state.view==="challenges")challengeList();else if(state.view==="topology")topology();else if(state.view==="scoreboard")scoreboard();else if(state.view==="vendors")vendors();else if(state.view.startsWith("page:"))openPage(state.view.slice(5)).catch(e=>toast(e.message));else if(state.view==="admin")renderAdmin();else home()}
function captureChallengeContext(){return{id:state.activeChallenge?.id,title:state.activeChallenge?.title,view:state.view,answer:dialog.querySelector('[name="answer"]')?.value??null,choices:$$('[name="choice"]:checked',dialog).map(x=>x.value),openHints:$$('.hint-card[open]',dialog).map(x=>x.dataset.hintIndex),scrollTop:dialog.querySelector('.dialog-body')?.scrollTop||0}}
async function openChallenge(id,options={}){
 try{
  const context=options.context||(options.preserve&&state.activeChallenge?.id===id?captureChallengeContext():null),restore=context?.id===id,draft=restore?context.answer:null,choices=restore?context.choices:[],openHints=restore?context.openHints:[],scrollTop=restore?context.scrollTop:0;
  const c=await api("/api/challenges/"+encodeURIComponent(id));state.activeChallenge=c;
  const prereqs=(c.requires||[]).map(x=>state.challenges.find(y=>y.id===x)?.title||x),unlocked=c.unlockedHints||[],next=(c.hints||[])[unlocked.length],free=c.answerType==="manual"||c.requiresApproval;
  const available=Number.isFinite(c.availablePoints)?c.availablePoints:Math.max(0,Number(c.points)-unlocked.reduce((sum,h)=>sum+Number(h.cost||0),0)),question=c.question||(free?'What would you like to share with your instructor?':'What flag did you find while completing this challenge?'),answerHelp=c.answerHelp||(free?'Write your response below. Your instructor will review it.':'Enter the value you found in the lab.');
  let answer="";
  const answerAttrs=' id="challenge-answer" aria-labelledby="flag-question" aria-describedby="flag-help" required';
  if(c.answerType==="choice")answer=c.multiple?'<div role="group" aria-labelledby="flag-question" aria-describedby="flag-help">'+(c.choices||[]).map(x=>'<label class="check-row"><input type="checkbox" name="choice" value="'+esc(x)+'">'+esc(x)+'</label>').join("")+'</div>':'<select class="select" name="answer"'+answerAttrs+'><option value="">Choose an answer…</option>'+(c.choices||[]).map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join("")+'</select>';
  else answer=free?'<textarea class="textarea" name="answer"'+answerAttrs+' placeholder="Write your response"></textarea>':'<input class="input" name="answer"'+answerAttrs+' autocomplete="off" spellcheck="false" autocapitalize="off" placeholder="Enter your flag">';
  const hintCards=unlocked.map(h=>'<details class="hint-card" data-hint-index="'+h.index+'" '+(openHints.includes(String(h.index))||options.openHint===h.index?'open':'')+'><summary class="hint-top"><span class="hint-title">'+esc(h.title)+'</span><span class="badge">−'+Number(h.cost||0)+' pts</span><span class="hint-toggle"><span>Show hint</span><span>Hide hint</span></span></summary><div class="markdown">'+markdown(h.content)+'</div></details>').join("");
  const challengeNetwork=c.locked?'':challengeTopologyMarkup(c),networkFirst=/creating the plc/i.test(c.title||'');
  const milestone=incidentMilestones.find(x=>x.min===topologyStageForChallenge(c));
  const impact=c.solved&&milestone?'<div class="challenge-impact '+milestone.tone+'"><strong>✦ Brewery status updated: '+esc(milestone.title)+'</strong><p>'+esc(milestone.body)+'</p><button class="button secondary small" data-action="view-full-topology">See the updated map →</button></div>':'';
  const nextCard=next&&!c.solved&&!c.skipped&&!c.hintAccessChanged?'<div class="hint-card"><div class="hint-top"><span class="hint-title">'+esc(next.title)+'</span>'+(state.user?'<button class="button secondary small" data-action="unlock-hint" data-id="'+esc(c.id)+'" data-index="'+next.index+'">Unlock · −'+Number(next.cost||0)+' pts</button>':'<button class="button secondary small" data-action="auth" data-mode="login">Sign in to unlock</button>')+'</div><p class="small-muted">Unlocking this hint leaves '+Math.max(0,available-Number(next.cost||0))+' of '+Number(c.points)+' points available when you solve.</p></div>':"";
  const guidance=(c.hints||[]).length||c.hintAccessChanged?(c.hintNotice?'<div class="notice warning">'+esc(c.hintNotice)+'</div>':'')+'<div class="section-head"><div><h3>Hints</h3><p>Unlock hints in order, then click a hint to expand it. Costs are deducted when you solve.</p></div></div><div class="hint-list">'+hintCards+nextCard+'</div>':"";
  const submission=c.locked?'':'<section class="challenge-answer-section"><p class="eyebrow">'+(free?'Your response':'Flag question')+'</p><h3 id="flag-question">'+esc(question)+'</h3><p class="answer-help" id="flag-help">'+esc(answerHelp)+'</p>'+(c.solved?'<div class="notice success">Challenge complete. Your score has been updated.</div>':c.skipped?'<div class="notice skipped-notice">Skipped by your facilitator. No points were awarded; the next challenge is unlocked.</div>':c.pending?'<div class="notice warning">Your response is waiting for an instructor to review it.</div>':state.user?'<form id="solve-form" data-id="'+esc(c.id)+'">'+answer+'<button class="button primary">'+(free?"Send for review":"Submit flag")+'</button><p id="solve-message" role="status" aria-live="polite"></p></form>':'<div class="notice"><button class="button secondary small" data-action="auth" data-mode="login">Sign in to submit</button></div>')+'</section>';
  const sequence=state.challenges.filter(x=>x.visible||x.id===c.id).sort((a,b)=>a.order-b.order||a.title.localeCompare(b.title)),position=sequence.findIndex(x=>x.id===c.id),following=position<0?null:sequence[position+1];
  const nextHelp=following&&!c.solved&&!c.skipped?(c.pending?'Next challenge unlocks after instructor approval.':c.locked?'Complete the prerequisite and solve this challenge first.':'Submit the correct flag to unlock Next challenge.'):following?.locked?'The next objective has another prerequisite.':'';
  const navigation='<nav class="challenge-sequence" aria-label="Challenge navigation"><div><span class="eyebrow">'+(following?'Up next':'End of workshop')+'</span><strong>'+esc(following?.title||'You have reached the last challenge')+'</strong>'+(nextHelp?'<small>'+esc(nextHelp)+'</small>':'')+'</div>'+(following?'<button class="button primary" type="button" data-action="next-challenge" data-id="'+esc(following.id)+'" '+(c.solved||c.skipped?'':'disabled')+'>Next challenge →</button>':'<button class="button secondary" type="button" data-action="back-to-challenges">Back to challenges</button>')+'</nav>';
  dialog.innerHTML='<div class="dialog-head"><div><p class="eyebrow">'+esc(c.category)+'</p><h2 tabindex="-1">'+esc(c.title)+'</h2></div><button class="icon-button" data-action="close-challenge" aria-label="Close challenge">×</button></div><div class="dialog-body"><div class="modal-meta">'+roleChip(roleForText(c.title+" "+c.category))+'<span class="badge">'+Number(c.points)+' points</span>'+((unlocked.length||available<Number(c.points))&&!c.solved?'<span class="badge">'+available+' / '+Number(c.points)+' points available</span>':'')+'<span class="badge">'+(free?"Instructor review":c.answerType==="regex"?"Pattern answer":"Flag required")+'</span>'+(c.solved?'<span class="badge solved">Solved</span>':c.skipped?'<span class="badge skipped">Skipped by facilitator</span>':"")+'</div><div class="challenge-map-link '+(state.topologyNotice?'is-updated':'')+'"><button class="button '+(state.topologyNotice?'primary':'secondary')+' small" type="button" data-action="view-full-topology">⌘ View full network topology →'+(state.topologyNotice?'<span class="map-update-badge">✦ Updated</span>':'')+'</button><span>'+(state.topologyNotice?'Your network map has changed. Open it to see what is new.':'The map updates as you solve challenges.')+'</span></div>'+(c.locked?'<div class="notice warning">Locked. Complete first: '+prereqs.map(esc).join(", ")+'</div>':(networkFirst?challengeNetwork:'')+'<section class="markdown">'+markdown(c.objective)+'</section>'+(networkFirst?'':challengeNetwork)+guidance)+impact+submission+navigation+'</div>';
  if(!dialog.open)dialog.showModal();
  if(restore){if(draft!==null&&dialog.querySelector('[name="answer"]'))dialog.querySelector('[name="answer"]').value=draft;$$('[name="choice"]',dialog).forEach(input=>input.checked=choices.includes(input.value));dialog.querySelector('.dialog-body').scrollTop=scrollTop;}
  if(options.openHint!==undefined)dialog.querySelector('[data-hint-index="'+options.openHint+'"]')?.scrollIntoView({block:'nearest'});
  if(options.focusTitle)dialog.querySelector('.dialog-head h2')?.focus({preventScroll:true});
 }catch(e){toast(e.message)}
}
function authView(mode){
 state.authChallengeContext=dialog.open?captureChallengeContext():null;
 const setup=mode==="setup",reg=mode==="register",heading=setup?"Create the workshop admin":reg?"Create participant account":"Sign in";

 auth.innerHTML='<div class="auth-intro"><p class="eyebrow">'+(setup?"First-time setup":"Workshop access")+'</p><h2>'+heading+'</h2><p>'+(setup?"This account controls challenges, hints, vendor pages, scoring, and participants.":reg?"Join the workshop with a participant account.":"Enter your workshop account details.")+'</p></div><form class="auth-form" id="auth-form" data-mode="'+mode+'">'+(setup||reg?'<div class="field"><label>Display name</label><input class="input" name="displayName"></div>':"")+'<div class="field"><label>Username</label><input class="input" name="username" required minlength="3" autocomplete="username"></div><div class="field"><label>Password</label><input class="input" name="password" type="password" required minlength="12" autocomplete="'+(setup||reg?"new-password":"current-password")+'"><small>Use at least 12 characters.</small></div>'+(reg?'<div class="field"><label>Team (optional)</label><input class="input" name="team"></div>':"")+'<div class="inline-form"><button class="button primary">'+(setup?"Create admin":reg?"Create account":"Sign in")+'</button><button class="button ghost" type="button" data-action="close-auth">Cancel</button></div><p class="small-muted" id="auth-error"></p>'+(reg?"":'<p class="small-muted">'+(state.settings.registrationOpen?'Need an account? <button class="button ghost small" type="button" data-action="auth" data-mode="register">Join</button>':"Ask the workshop admin for an account.")+'</p>')+'</form>';
 auth.showModal();
}
async function refresh(data){
 const previousUser=state.user?.id,previousSolved=new Set(state.challenges.filter(c=>c.solved||c.skipped).map(c=>c.id)),wasInitialized=state.initialized;
 const d=data||await api("/api/public");Object.assign(state,{settings:d.settings,user:d.user,challenges:d.challenges,pages:d.pages,scoreboard:d.scoreboard,progress:d.progress||{score:0,solves:0},needsSetup:d.needsSetup,revealedTopologyAddresses:d.revealedTopologyAddresses||{}});
 const newlySolved=wasInitialized&&previousUser&&d.user?.id===previousUser&&state.challenges.some(c=>(c.solved||c.skipped)&&!previousSolved.has(c.id));
 if(newlySolved)state.topologyPreviewStage=null;
 state.initialized=true;
 updateTopologyNotice();
 updateChallengeNotice();
 if(state.view==="topology"&&state.topologyNotice){state.topologyJustUpdated=true;markTopologyViewed()}
 if(state.needsSetup){authView("setup");return}
 if(state.view==="admin"&&state.user?.role!=="admin")state.view="home";
 routeView();
}
let progressPollRunning=false;
async function pollChallengeProgress(){
 if(progressPollRunning||document.hidden||!state.initialized||state.user?.role!=="participant")return;
 progressPollRunning=true;
 try{
  const data=await api("/api/public");
  if(data.user?.id!==state.user.id)return;
  const previous=new Map(state.challenges.map(c=>[c.id,String(c.solved)+":"+String(c.skipped)+":"+String(c.locked)]));
  if(!data.challenges.some(c=>previous.get(c.id)!==String(c.solved)+":"+String(c.skipped)+":"+String(c.locked)))return;
  const context=dialog.open?captureChallengeContext():null;
  await refresh(data);
  if(context?.id&&dialog.open)await openChallenge(context.id,{context});
  if(state.topologyNotice||state.topologyJustUpdated)toast("Your progress and network topology have been updated.");
 }catch{}finally{progressPollRunning=false}
}
setInterval(pollChallengeProgress,15000);
setInterval(async()=>{if(document.hidden||state.view!=='admin'||state.adminTab!=='progress'||state.user?.role!=='admin')return;try{const data=await api('/api/admin/workshop');state.admin=data;const el=$('.admin-content');if(el)el.innerHTML=adminProgress()}catch{}},15000);
