function adminNav(){return'<nav class="admin-nav">'+[["challenges","Challenges"],["answer-key","Question & answer key"],["topology-addresses","Topology addresses"],["pages","Pages & vendors"],["media","Media library"],["users","Participants"],["review","Submissions"],["progress","Live progress"],["issues","Common issues"],["skips","Skip challenges"],["settings","Workshop settings"]].map(([id,l])=>'<button class="admin-tab '+(state.adminTab===id?"active":"")+'" data-admin-tab="'+id+'">'+l+'</button>').join("")+"</nav>"}
