 if(!state.admin){shell('<div class="empty">Opening admin studio…</div>',"Admin studio");loadAdmin().then(renderAdmin).catch(e=>toast(e.message));return}
 const content=state.adminTab==="challenges"?adminChallenges():state.adminTab==="answer-key"?adminAnswerKey():state.adminTab==="topology-addresses"?adminTopologyAddresses():state.adminTab==="pages"?adminPages():state.adminTab==="media"?adminMedia():state.adminTab==="users"?adminUsers():state.adminTab==="review"?adminReview():state.adminTab==="progress"?adminProgress():state.adminTab==="issues"?adminIssues():state.adminTab==="skips"?adminSkips():adminSettings();
