document.addEventListener("keydown",e=>{const node=e.target instanceof Element?e.target.closest('[data-topology-node]'):null;if(node&&(e.key==='Enter'||e.key===' ')){e.preventDefault();selectTopologyNode(node.dataset.topologyNode)}});
document.addEventListener("keydown",e=>{const target=e.target instanceof Element?e.target:null,graph=target?.closest(".challenge-topology-graph"),image=target?.closest(".markdown img, .product-photo img");if(graph&&(e.key==="Enter"||e.key===" ")){e.preventDefault();openTopologyViewer(graph);return}if(image&&(e.key==="Enter"||e.key===" ")){e.preventDefault();openImageViewer(image);return}if(!imageViewer.open)return;if(e.key==="+"||e.key==="="){e.preventDefault();setImageViewerScale(imageScale*1.2)}else if(e.key==="-"){e.preventDefault();setImageViewerScale(imageScale/1.2)}else if(e.key==="0"){e.preventDefault();fitImageViewer()}});
