 const viewerAction=e.target.closest("[data-viewer-action]");if(viewerAction){if(viewerAction.dataset.viewerAction==="close")imageViewer.close();else if(viewerAction.dataset.viewerAction==="zoom-in")setImageViewerScale(imageScale*1.2);else if(viewerAction.dataset.viewerAction==="zoom-out")setImageViewerScale(imageScale/1.2);else if(viewerAction.dataset.viewerAction==="reset")fitImageViewer();return}
 const device=e.target.closest('[data-topology-node]');if(device){selectTopologyNode(device.dataset.topologyNode);return}
 const topologyGraph=e.target.closest(".challenge-topology-graph");if(topologyGraph){openTopologyViewer(topologyGraph);return}
 const image=e.target.closest(".markdown img, .product-photo img");if(image){openImageViewer(image);return}
 const nav=e.target.closest("[data-view]");if(nav){e.preventDefault();rememberAdminDraft();state.view=nav.dataset.view;if(state.view==="topology"){state.topologyJustUpdated=state.topologyNotice;markTopologyViewed();state.topologyPreviewStage=null}else if(state.view==="challenges")markChallengesViewed();$("#sidebar")?.classList.remove("open");routeView();return}
 const internal=e.target.closest(".markdown a[href^='/']");
 if(internal){const slug=internal.getAttribute("href").slice(1).replace(/\/+$/,"").toLowerCase();const target=state.pages.find(x=>x.slug===slug);if(target){e.preventDefault();if(dialog.open){state.challengeReturnContext=captureChallengeContext();dialog.close()}state.view="page:"+target.slug;openPage(target.slug).catch(x=>toast(x.message));return}}
 const pg=e.target.closest("[data-page]");if(pg){state.view="page:"+pg.dataset.page;openPage(pg.dataset.page).catch(x=>toast(x.message));return}
